  a[n++] = &s_wrist_flex;
  static bridge::StsServo s_elbow_flex(sts, 3, 2048, 1, -1.690f, 1.690f);   // elbow_flex: raw 2048 = 0 rad; calibrate the offset per servo
  a[n++] = &s_elbow_flex;
  static bridge::StsServo s_shoulder_lift(sts, 2, 2048, 1, -1.745f, 1.745f);   // shoulder_lift: raw 2048 = 0 rad; calibrate the offset per servo
  a[n++] = &s_shoulder_lift;
  static bridge::StsServo s_shoulder_pan(sts, 1, 2048, 1, -1.920f, 1.920f);   // shoulder_pan: raw 2048 = 0 rad; calibrate the offset per servo
  a[n++] = &s_shoulder_pan;
